       UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'toProduct' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 12 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'toSite' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 14 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'valuationType' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 11 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'yyyymm' COL_NM, 'CLOB' DATA_TP_CD, 'IN' COL_TP_CD, 18 SORT_ORD FROM DUAL) S
   ON (NVL(TO_CHAR(T.PROC_NM), '~') = NVL(TO_CHAR(S.PROC_NM), '~') AND NVL(TO_CHAR(T.COL_NM), '~') = NVL(TO_CHAR(S.COL_NM), '~') AND NVL(TO_CHAR(T.COL_TP_CD), '~') = NVL(TO_CHAR(S.COL_TP_CD), '~'))
 WHEN MATCHED THEN UPDATE SET T.DATA_TP_CD = S.DATA_TP_CD, T.SORT_ORD = S.SORT_ORD, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.DATA_TP_CD, S.DATA_TP_CD, 0, 1) = 1 OR DECODE(T.SORT_ORD, S.SORT_ORD, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (PROC_NM, COL_NM, DATA_TP_CD, COL_TP_CD, SORT_ORD, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.PROC_NM, S.COL_NM, S.DATA_TP_CD, S.COL_TP_CD, S.SORT_ORD, 'admin', SYSDATE, 'admin', SYSDATE);

