  FROM (SELECT 'SCP Tester' USER_GR_ID, 'SCP0111' MNU_ID, 'main' SHT_NM, 'SAVE' MNU_BTN_CD, 'N' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M T WHERE NVL(TO_CHAR(T.USER_GR_ID), '~') = NVL(TO_CHAR(S.USER_GR_ID), '~') AND NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'));
