SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'LineByOperationPlantId_SCP_ALL' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP_ALL] AS-IS UP_FX_GetCommonDataList_SCP_ALL @Code=''LineByOperationPlantId''' SQL_NM, 'SELECT A.LINE_ID AS CODE , A.LINE_ID || '' '' || A.LINE_NAME AS NAME , A.DIVISION_ID AS DIVISION_ID , A.OPERATION_GROUP_ID AS SHOP_GROUP_ID , A.PLANT_ID AS PLANT_ID , A.FACTORY_ID AS FACTORY_ID FROM SCM_LINE_HIERARCHY_CPS_V_SN A WHERE 1=1 GROUP BY A.LINE_ID , A.LINE_NAME , A.DIVISION_ID , A.OPERATION_GROUP_ID , A.PLANT_ID , A.FACTORY_ID ORDER BY UPPER(A.LINE_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Measure' SQL_ID, 'DM' MDU_DIVS_CD, '[C] AS-IS @Code=''Measure'' 변환 — @Param1→@mnuId · @Param2→@sheetName' SQL_NM, 'SELECT DISTINCT A.COLUMN_NAME AS CODE, CASE WHEN A.COLUMN_NAME = ''CUST_FCST_EDI_ORG'' THEN '' └ '' || ''EDI[Org.]'' WHEN A.COLUMN_NAME = ''CUST_FCST_EDI'' THEN '' └ '' || ''EDI'' ELSE A.COLUMN_LABEL_NAME END AS NAME FROM SCM_MGR.SCM_MST_SHEET_MEASURE A WHERE A.PROGRAM_ID = @mnuId AND ( @sheetName IS NULL OR A.SHEET_NAME = @sheetName ) AND A.VALID_YN = ''Y'' UNION ALL SELECT MEASURE AS CODE, '' └ '' || MEASURE AS NAME FROM SCM_MGR.DM_MST_CUSTOMER_FCST WHERE VALID_YN = ''Y'' AND MEASURE IS NOT NULL AND MEASURE_GROUP = ''CUST_FCST'' AND @mnuId IN (''DMF0003'', ''DMF0035'', ''DMF0003_TEST'') GROUP BY MEASURE UNION ALL SELECT ''Immidiate'', ''    └ '' || ''Immidiate'' FROM DUAL UNION ALL SELECT ''Planning_Forecast'', ''    └ '' || ''Planning_Forecast'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement'', ''    └ '' || ''Commercial_Agreement'' FROM DUAL UNION ALL SELECT ''Firm_Temp'', ''    └ '' || ''Firm_Temp'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp'', ''    └ '' || ''Manumacturing_Material_Temp'' FROM DUAL UNION ALL SELECT ''Material_Temp'', ''    └ '' || ''Material_Temp'' FROM DUAL UNION ALL SELECT ''Backorder'', ''    └ '' || ''Backorder'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[P+P]'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[P+P]'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Immidiate[Org.]'', ''    └ '' || ''Immidiate[Org.]'' FROM DUAL UNION ALL SELECT ''Planning_Forecast[Org.]'', ''    └ '' || ''Planning_Forecast[Org.]'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement[Org.]'', ''    └ '' || ''Commercial_Agreement[Org.]'' FROM DUAL UNION ALL SELECT ''Firm_Temp[Org.]'', ''    └ '' || ''Firm_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp[Org.]'', ''    └ '' || ''Manumacturing_Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Material_Temp[Org.]'', ''    └ '' || ''Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Backorder[Org.]'', ''    └ '' || ''Backorder[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[Org.]'', '' └ '' || ''EXCEL[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[Org.]'', '' └ '' || ''RPA[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Ship Plan'', ''Ship Plan'' FROM DUAL UNION ALL SELECT ''CUST_FCST_EDI'', '' └ '' || ''EDI'' FROM DUAL' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'PlanType1_SCP_ALL' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP_ALL] AS-IS UP_FX_GetCommonDataList_SCP_ALL @Code=''PlanType1''' SQL_NM, 'SELECT PLAN_TYPE AS CODE , PLAN_TYPE AS NAME , MAX(PLAN_TYPE_ORDER) PLAN_TYPE_ORDER , DIVISION_ID AS DIVISION_ID , PLAN_START_YYYYMMDD AS PLANDATE FROM SCP_PLAN_VERSION_V WHERE 1=1 GROUP BY PLAN_TYPE , DIVISION_ID , PLAN_START_YYYYMMDD ORDER BY PLAN_TYPE_ORDER , UPPER(DIVISION_ID) , UPPER(PLAN_START_YYYYMMDD)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Plant' SQL_ID, 'ALL' MDU_DIVS_CD, '[공통] AS-IS UP_FX_GetCommonDataList @Code=''Plant''' SQL_NM, 'SELECT distinct S.PLANT_ID AS CODE , MAX((CASE WHEN A.PLANT_NAME IS NULL THEN V.VENDOR_NAME ELSE A.PLANT_NAME END )) AS NAME FROM SCM_MST_SITE S LEFT OUTER JOIN SCM_MST_PLANT_SN A ON A.DIVISION_ID = S.DIVISION_ID AND A.PLANT_ID = S.PLANT_ID LEFT OUTER JOIN SCM_MST_VENDOR V ON V.VENDOR_CODE = S.PLANT_ID WHERE (@divisionId IS NULL OR S.DIVISION_ID = @divisionId) AND ( (@plantId IS NULL OR S.PLANT_ID LIKE ''%'' || @plantId || ''%'') OR (@plantId IS NULL OR PLANT_NAME LIKE ''%'' || @plantId || ''%'') ) AND S.VALID_YN =''Y'' GROUP BY S.PLANT_ID ORDER BY UPPER(S.PLANT_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SCPPlanPeriod_SCP' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP] AS-IS UP_FX_GetCommonDataList_SCP @Code=''SCPPlanPeriod''' SQL_NM, 'SELECT HORIZON_START_DATE ,HORIZON_END_DATE ,PLAN_CYCLE ,(TRUNC(TO_DATE(HORIZON_END_DATE, ''YYYYMMDD'') + 1, ''IW'') - TRUNC(TO_DATE(PLAN_NAME, ''YYYYMMDD'') + 1, ''IW'')) / 7 AS DIFF_WEEK FROM SCM_MST_PLAN WHERE 1 = 1 AND PLAN_NAME = @planName AND DIVISION_ID = @divisionId AND PLAN_CYCLE = ''WEEKLY''' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD, 'Lookup System' SQL_NM, '    SELECT  T1.SEGMENT1 CODE, T1.SEGMENT2 NAME' || CHR(13) || CHR(10) || '     FROM  SCM_ADM_LOOKUP_MASTER_DETAIL T1' || CHR(13) || CHR(10) || '    WHERE  1=1' || CHR(13) || CHR(10) || '      AND  T1.LOOKUP_TYPE = ''SYSTEM''' || CHR(13) || CHR(10) || '      AND  T1.VALID_YN = ''Y''' || CHR(13) || CHR(10) || ' ORDER BY  T1.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));

COMMIT;
